def forward(groups):
    text = f"{groups[1]} {groups[2].zfill(2)} {groups[3]} {groups[4]}"
    dt = datetime.strptime(text, '%b %d %H:%M:%S %Y')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%a %b %d %H:%M:%S %Y')

